'use strict';
const $ = (id) => document.getElementById(id);
let config, voices = [], currentTab = 'create', polling = false, activeOutputId = null;
function isHmongStudio(){return config?.variant==='hmong';}
function hmongSteps(){const steps=Number($('hmong-steps')?.value||config?.hmong_steps||16);return [4,8,16,32].includes(steps)?steps:16;}
const hmongEmotions=['neutral','warm','joyful','sad','serious','suspense'];
function hmongExpressionSettings(){
 const emotion=$('hmong-emotion')?.value;
 const strength=Number($('hmong-emotion-strength')?.value);
 return {emotion:hmongEmotions.includes(emotion)?emotion:'warm',emotion_strength:Number.isFinite(strength)&&strength>=0&&strength<=1?strength:0.65,auto_rhythm:$('hmong-auto-rhythm')?.checked??true,delivery:$('delivery')?.value||'story',paragraph_pause:Number($('paragraph-pause')?.value||0)};
}
function hmongExpressionChanged(){
 if(typeof workspaceBusy!=='undefined'&&workspaceBusy)return;
 if(typeof workspaceInvalidate==='function')workspaceInvalidate();
 if(typeof workspaceFreeVoice!=='undefined'&&workspaceFreeVoice){workspaceFreeVoice=null;$('workspace-free-audio').pause();$('workspace-free-audio').hidden=true;$('workspace-free-status').textContent='Nhịp đọc hoặc sắc thái đã đổi. Tạo voice riêng lại để áp dụng thiết lập mới.';}
}
function updateHmongPauseLabels(){
 const label=$('hmong-auto-rhythm').checked?'Nghỉ bổ sung giữa câu/đoạn (giây)':'Nghỉ giữa các câu/đoạn (giây)';
 for(const id of ['paragraph-pause','dub-hmong-paragraph-pause'])document.querySelector('label[for="'+id+'"]').textContent=label;
}
function insertHmongScriptControl(emotion){
 const field=$('script'),start=field.selectionStart,end=field.selectionEnd,selected=field.value.slice(start,end);
 const replacement='[emotion='+emotion+'] '+selected+(selected?' [emotion='+hmongExpressionSettings().emotion+'] ':'');
 field.setRangeText(replacement,start,end,'end');field.focus();field.oninput();
}
function setupHmongExpressionControls(){
 const dubSettings=$('dub-hmong-settings');document.querySelector('#panel-dub .workspace-voice-tools').append(dubSettings);
 $('dub-hmong-delivery').replaceChildren(...[...$('delivery').options].map(option=>option.cloneNode(true)));
 const delivery=[...$('delivery').options].some(option=>option.value===config.delivery)?config.delivery:'story';
 const emotion=hmongEmotions.includes(config.emotion)?config.emotion:'warm';
 const configuredStrength=Number(config.emotion_strength??0.65),strength=Number.isFinite(configuredStrength)&&configuredStrength>=0&&configuredStrength<=1?configuredStrength:0.65;
 for(const id of ['delivery','dub-hmong-delivery'])$(id).value=delivery;
 for(const id of ['hmong-emotion','dub-hmong-emotion'])$(id).value=emotion;
 for(const id of ['hmong-emotion-strength','dub-hmong-emotion-strength']){$(id).value=String(strength);$(id+'-value').textContent=Math.round(strength*100)+'%';}
 for(const id of ['hmong-auto-rhythm','dub-hmong-auto-rhythm'])$(id).checked=typeof config.auto_rhythm==='boolean'?config.auto_rhythm:true;
 $('dub-hmong-paragraph-pause').value=$('paragraph-pause').value;
 for(const [left,right]of [['delivery','dub-hmong-delivery'],['hmong-emotion','dub-hmong-emotion'],['hmong-emotion-strength','dub-hmong-emotion-strength'],['hmong-auto-rhythm','dub-hmong-auto-rhythm'],['paragraph-pause','dub-hmong-paragraph-pause']]){
  for(const [source,target]of [[left,right],[right,left]])$(source).addEventListener(source.includes('strength')||source.includes('pause')?'input':'change',()=>{
   if(source.includes('auto-rhythm'))$(target).checked=$(source).checked;else $(target).value=$(source).value;
   if(source.includes('strength'))for(const id of [left,right])$(id+'-value').textContent=Math.round(Number($(id).value)*100)+'%';
   updateHmongPauseLabels();hmongExpressionChanged();
  });
 }
 updateHmongPauseLabels();
 document.querySelectorAll('[data-hmong-emotion]').forEach(button=>button.onclick=()=>insertHmongScriptControl(button.dataset.hmongEmotion));
 $('hmong-insert-example').onclick=()=>{const field=$('script');field.setRangeText('Nyob zoo. **Ua tsaug.** [pause=0.5] [emotion=warm]Ua tsaug rau koj mloog.',field.selectionStart,field.selectionEnd,'end');field.focus();field.oninput();};
}
function hideStudioControl(id){const node=$(id);if(node)node.hidden=true;document.querySelectorAll('label[for="'+id+'"]').forEach(label=>label.hidden=true);}
function applyStudioVariant(){
 if(!isHmongStudio())return;
 document.title=config.app_name||'Voice Studio Hmong';
 const intro=document.querySelector('#panel-create .page-heading > p');if(intro)intro.textContent='Tạo lời đọc Hmong Trắng / Hmoob Daw từ văn bản và mẫu giọng của bạn.';
 const languageFeature=document.querySelector('#panel-create .feature[data-tab="voices"] p');if(languageFeature)languageFeature.textContent='Hai mẫu nam/nữ Hmong và các giọng cá nhân đã thêm.';
 const brand=document.querySelector('.brand');if(brand){brand.setAttribute('aria-label',document.title);const name=brand.querySelector(':scope > span:last-child');if(name){name.replaceChildren(document.createTextNode(document.title),element('small','PHÒNG THU TIẾNG HMONG'));}}
 for(const id of ['language','clone-language','writing-language','dub-language']){if([...$(id).options].some(option=>option.value===config.default_language))$(id).value=config.default_language;}
 for(const id of ['quality','nano-parallel','nano-threads','nano-steps','dub-nano-steps','dub-parallel','use-nano','target-preset','create-fast','studio-fast','workspace-processing','asr-language','asr-quality','editor-recognize','auto-subtitles','auto-dub','workspace-all','workspace-system-help','dub-add-system-voice'])hideStudioControl(id);
 const targetNote=$('benchmark-speed')?.nextElementSibling;if(targetNote?.tagName==='P')targetNote.hidden=true;
 const localNote=document.querySelector('#panel-create .local-note');if(localNote)localNote.textContent='Mặc định 16 bước và nhịp kể chuyện tự động. Nhịp tự động có thể tạo lâu hơn; tắt để ưu tiên tốc độ. 4/8 bước chỉ dùng bản nháp, có thể đọc thiếu hoặc kém rõ. Riêng 4 bước có thể dùng INT8 để tự tăng tốc CPU, tự quay về độ chính xác gốc nếu không phù hợp. Mô hình được giữ trong RAM cho lượt sau.';
 for(const id of ['hmong-settings','dub-hmong-settings','hmong-asr-note','hmong-script-controls'])$(id).hidden=false;
 $('hmong-reference-note').textContent=(config.hmong_ready?'Mô hình Hmong đã sẵn sàng. Tạo giọng có thể chậm trên CPU; không cam kết 1 giờ voice trong 2 phút. ':'Lần chuẩn bị đầu cần Internet và dung lượng trống để tải/kiểm tra mô hình từ nguồn gốc. Bấm Tải model hoặc làm theo hướng dẫn của gói. ')+(config.hmong_reference_note||'Dùng mẫu tham chiếu Hmong rõ lời. Với giọng cá nhân, cần mẫu 3–8 giây và lời khớp chính xác đoạn thu.');
 for(const id of ['hmong-steps','dub-hmong-steps'])$(id).value=String([4,8,16,32].includes(Number(config.hmong_steps))?Number(config.hmong_steps):16);
 $('paragraph-pause').value='0';
 setupHmongExpressionControls();
 for(const [id,other]of [['hmong-steps','dub-hmong-steps'],['dub-hmong-steps','hmong-steps']])$(id).onchange=()=>{$(other).value=$(id).value;hmongExpressionChanged();};
 for(const id of ['create-native','workspace-native'])$(id).replaceChildren(new Option('Tất cả giọng','all'),new Option('Hmong','mww'),new Option('Giọng cá nhân','cloned'));
 for(const id of ['voice-source','dub-voice-source'])$(id).replaceChildren(new Option('Tất cả nguồn','all'),new Option('Giọng AI Hmong','ai'));
 const transcript=$('transcript');transcript.required=true;transcript.placeholder='Nhập đúng lời Hmong trong đoạn 3–8 giây đang chọn. Hai MP3 đi kèm được điền lời mẫu bạn đã cung cấp sau khi đối chiếu tệp; có thể nghe và sửa nếu cần.';
 const transcriptLabel=document.querySelector('label[for="transcript"]');if(transcriptLabel)transcriptLabel.textContent='Kiểm tra / sửa lời Hmong cho khớp đoạn mẫu 3–8 giây (bắt buộc)';
 const sampleNote=document.querySelector('label[for="clone-file"] small');if(sampleNote)sampleNote.textContent='Tệp 3–30 giây · chọn đoạn 3–8 giây bên dưới · WAV/MP3/M4A/FLAC/OGG/WEBM · tối đa 20 MB';
 const cloneLength=document.querySelector('#panel-clone .clone-intro p');if(cloneLength)cloneLength.textContent='Tải mẫu → chọn đoạn và lời → lưu hoặc tạo thử giọng';
 const cloneIntro=document.querySelector('#panel-clone .page-heading p');if(cloneIntro)cloneIntro.textContent='Có thể tải hai MP3 nam/nữ đi kèm. Tool đối chiếu tệp bằng SHA256 rồi điền lời mẫu. Với hai mẫu đi kèm, lời do bạn cung cấp và xác nhận khớp đoạn thu. Bạn vẫn có thể nghe và sửa; mẫu khác cần lời khớp đoạn 3–8 giây đang chọn.';
 $('clone-reference').hidden=false;$('clone-save-test').hidden=false;
 $('clone-submit').textContent='◎ Lưu hồ sơ giọng';
 const cloneNote=$('clone-form').lastElementChild;if(cloneNote)cloneNote.textContent='Lưu hồ sơ chỉ chuẩn bị mẫu tham chiếu. Chọn “Lưu và tạo thử giọng Hmong” để tạo một bản thu thật và theo dõi tiến độ ở Tạo giọng. Có thể tải WAV/MP3 sau khi tạo xong.';
 const help=$('help-dialog');help.querySelector('h2').textContent='Phòng thu giọng Hmong cục bộ';const helpList=help.querySelector('ol');helpList.replaceChildren(...['Lần chuẩn bị đầu cần Internet để tải và kiểm tra mô hình Hmong từ nguồn gốc; không dùng bộ tải giọng Việt/Anh.', 'Giọng cá nhân cần mẫu Hmong 3–8 giây và lời khớp chính xác mẫu. Nhập chữ Hmong RPA, giữ đủ chữ đuôi ghi thanh điệu.', 'Dùng 16 bước mặc định hoặc 32 bước để tăng chất lượng. 4/8 bước là bản nháp, có thể kém rõ. Riêng 4 bước tự thử INT8 trên CPU nếu phù hợp; 16/32 bước giữ độ chính xác gốc. Nghe kiểm tra trước khi sử dụng.', 'Sắc thái thay đổi nhịp, cường độ và khoảng nghỉ, không phải cảm xúc được huấn luyện trong mô hình. Không đổi cao độ để tránh ảnh hưởng thanh điệu Hmong. Nhịp tự động có thể tạo lâu hơn; tắt để ưu tiên tốc độ.'].map(text=>element('li',text)));const helpNotes=help.querySelectorAll(':scope > p');if(helpNotes[0])helpNotes[0].textContent='Tool lưu từng đoạn để có thể dừng và tiếp tục. Suy luận Hmong có thể chậm trên CPU; giới hạn thời lượng âm thanh không phải cam kết thời gian xử lý.';if(helpNotes[1])helpNotes[1].textContent=config.hmong_reference_note||'Chất lượng Hmong và độ giống giọng phụ thuộc mô hình, bản thu và lời tham chiếu; cần nghe đánh giá.';if(helpNotes[2])helpNotes[2].textContent='Chưa có nhận dạng Hmong từ video. Nhập hoặc sửa TXT/SRT thủ công. Các thẻ **nhấn**, [pause=0.5] và [emotion=warm] được xử lý trước khi tạo giọng, không được đọc thành lời.';
 $('benchmark-speed').textContent='◷ Đo tốc độ bằng mẫu đọc Hmong';
 $('workspace-status').textContent='Nhập phụ đề SRT Hmong hoặc thêm lời và mốc thủ công, rồi chọn giọng để tạo voice.';
 $('subtitle-health').textContent='Chưa hỗ trợ nhận dạng Hmong từ video. Bạn vẫn có thể nhập/sửa TXT/SRT và xuất video có voice/phụ đề.';
}

const samples = {mww:'Nyob zoo, kuv zoo siab tau ntsib koj. Hnub no peb yuav mloog ib zaj dab neeg. Ua tsaug rau koj mloog.',vi:'Có những câu chuyện bắt đầu bằng một lời chào. Có những ý tưởng chỉ cần một giọng nói để chạm đến trái tim. Chào mừng bạn đến với Voice Studio — nơi câu chữ của bạn cất thành lời.', 'en-US':'Every great story begins with a voice. Welcome to your personal studio, where a little imagination becomes something worth listening to.', 'en-GB':'Every great story begins with a voice. Welcome to your personal studio, where a little imagination becomes something worth listening to.', ja:'こんにちは。あなたの物語を、あなたらしい声で届けましょう。', ko:'안녕하세요. 당신만의 목소리로 새로운 이야기를 시작해 보세요.'};
function notify(message, error = false) { const el = $('notice'); el.textContent = message; el.classList.toggle('error', error); el.hidden = !message; }
async function api(path, options = {}) { if(isHmongStudio()&&path==='/api/speech'&&typeof options.body==='string'){const payload=JSON.parse(options.body);Object.assign(payload,hmongExpressionSettings(),{hmong_steps:hmongSteps()});options={...options,body:JSON.stringify(payload)};} let res;try{res=await fetch(path,options);}catch(e){throw new Error('Mất kết nối với tool. Giữ cửa sổ CMD mở; nếu đã tắt, chạy lại '+(isHmongStudio()?'MO_VOICE_STUDIO_HMONG.bat':'MO_VOICE_STUDIO.bat')+' và dùng tab vừa mở.');} if (!res.ok) { let detail; try { detail = (await res.json()).detail; } catch {} throw new Error(typeof detail === 'string' ? detail : `Yêu cầu không thành công (${res.status}). Kiểm tra dữ liệu và thử lại.`); } return res.status === 204 ? null : res.json(); }
function element(tag, text, cls) { const el = document.createElement(tag); if (text !== undefined) el.textContent = text; if (cls) el.className = cls; return el; }
function showTab(tab) { currentTab = tab; document.querySelectorAll('.panel').forEach(p => p.hidden = p.id !== `panel-${tab}`); document.querySelectorAll('.nav-item').forEach(b => b.classList.toggle('active', b.dataset.tab === tab)); $('breadcrumb').textContent = {create:'Văn bản thành giọng nói',dub:'Lồng tiếng video',writing:'AI viết kịch bản',clone:'Nhân bản giọng nói',voices:'Thư viện giọng',history:'Lịch sử bản thu'}[tab]; notify(''); if(tab === 'history') refreshHistory().catch(e=>notify(e.message,true)); if(tab === 'voices') renderVoices(); if(tab==='dub'){refreshDubSources().catch(e=>notify(e.message,true));} if(tab==='dub')$('dub-settings').textContent=`Nhịp đọc: ${$('speed').value}× · ${$('delivery').selectedOptions[0].textContent}. Chọn giọng lồng tiếng trực tiếp bên dưới.`; }
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>showTab(b.dataset.tab)));
function updateVoiceOptions() { const previous = $('voice').value; const available = voices.filter(v=>v.languages.includes($('language').value)&&($('voice-source').value==='all'||($('voice-source').value==='system'?(v.engine==='system'):(v.engine!=='system')))); $('voice').replaceChildren(...available.map(v=>{ const o = element('option',v.name + (v.native_language?' · '+(config.languages[v.native_language]||({'en':'Mỹ / Anh'}[v.native_language]||v.native_language)):'') + (v.ready===false?' · Chưa tải model':' · Sẵn sàng') + (v.category === 'cloned' ? ' · Cá nhân' : '')); o.value=v.id; return o; })); if(available.some(v=>v.id===previous)) $('voice').value=previous;else{const ready=isHmongStudio()?available.find(v=>v.ready!==false):(available.find(v=>v.engine==='vieneu_nano'&&config?.nano_ready)||available.find(v=>v.engine==='system'||(v.engine==='vieneu_nano'?config?.nano_ready:config?.models[v.engine])));if(ready)$('voice').value=ready.id;} updateVoice(); }
function updateVoice() { const v=voices.find(v=>v.id===$('voice').value); $('voice-label').textContent=v?.name || 'Chưa có giọng'; $('voice-detail').textContent=v?.description || ''; const engine=v?.engine || ($('language').value==='vi' ? 'vieneu':'qwen_clone'); const ready=engine==='system'?true:engine==='vieneu_nano' ? config?.nano_ready : config?.models[engine]; $('engine-info').textContent=!v?'Chưa có giọng phù hợp. Chọn giọng AI hoặc thêm giọng Windows.':engine==='system'?'Giọng Windows đã cài · không cần model AI':ready?`${engine} · Mô hình đã tải`:`${engine} · Cần tải mô hình`; $('generate').disabled=!v;if(typeof syncVoiceDownload==='function')syncVoiceDownload('create'); }
async function refreshVoices() { voices=(await api('/api/voices')).voices; updateVoiceOptions(); updateDubVoices(); renderVoices(); }
function renderVoices() { const search=$('voice-search').value.toLocaleLowerCase(); const list=voices.filter(v=>v.name.toLocaleLowerCase().includes(search)); $('voice-library').replaceChildren(); if(!list.length) $('voice-library').append(element('div','Chưa có giọng phù hợp. Hãy thêm giọng cá nhân.','empty')); for(const v of list) { const card=element('article',undefined,'voice-card card'); card.append(element('span','≋','voice-orb'),element('h3',v.name),element('p',v.description)); const tags=element('div',undefined,'tags'); tags.append(element('span',v.category==='cloned'?'GIỌNG CÁ NHÂN':'GIỌNG CÓ SẴN','tag')); for(const lang of v.languages.slice(0,4)) tags.append(element('span',config.languages[lang]||lang,'tag')); if(v.languages.length>4) tags.append(element('span',`+${v.languages.length-4}`,'tag')); card.append(tags); if(v.category==='cloned') { const audio=element('audio'); audio.controls=true; audio.preload='none'; audio.src=`/api/voices/${v.id}/sample`; card.append(audio); } const actions=element('div',undefined,'voice-actions'); const use=element('button','Sử dụng giọng →'); use.onclick=()=>{ $('language').value=v.languages[0];$('voice-source').value='all'; updateVoiceOptions(); $('voice').value=v.id; updateVoice(); showTab('create'); $('script').focus(); }; actions.append(use); if(v.category==='cloned') { const del=element('button','Xóa','delete'); del.onclick=async()=>{if(!confirm(`Xóa mẫu và hồ sơ giọng “${v.name}”?`))return; try{await api(`/api/voices/${v.id}`,{method:'DELETE'}); await refreshVoices();}catch(e){notify(e.message,true);} }; actions.append(del); } card.append(actions); $('voice-library').append(card); } }
$('voice-search').oninput=renderVoices;
$('language').onchange=updateVoiceOptions; $('voice').onchange=updateVoice;
$('script').oninput=()=>{$('char-count').textContent=`${$('script').value.length.toLocaleString('vi-VN')} / 200.000 ký tự`;};
$('sample-button').onclick=()=>{$('script').value=samples[$('language').value]||samples['en-US']; $('script').oninput();};
$('speed').oninput=()=>{$('speed-value').textContent=Number($('speed').value).toFixed(2)+'×';};
function setOutput(job) { if(activeOutputId && activeOutputId!==job.id)return;if(job.video_id||dubJob===job.id)updateDub(job);$('voice-progress').value=job.progress||0;$('voice-percent').textContent=`${job.progress||0}%`;const working=['queued','running','cancelling'].includes(job.status);$('stop-generation').hidden=!working;$('stop-generation').disabled=job.status==='cancelling';$('stop-generation').textContent=job.status==='cancelling'?'Đang dừng…':'■ Dừng tạo giọng'; $('output-title').textContent = {queued:'Bản thu đang trong hàng đợi…',running:'AI đang tạo giọng nói trên máy…',cancelling:'Đang dừng…',cancelled:'Đã dừng · Có thể tiếp tục trong Lịch sử',error:'Chưa tạo được bản thu',done:'Bản thu của bạn đã sẵn sàng'}[job.status]; $('output-subtitle').textContent=job.error || `${job.voice_name} · ${job.phase || ''} · ${job.progress || 0}% · ${duration(job.audio_seconds || 0)}${job.duration_limited ? ' · Đã đạt giới hạn; còn nội dung chưa đọc' : ''}`; const done=job.status==='done';showSpeedReport(job); $('output-audio').hidden=!done; $('download').hidden=!done; if(done){$('output-audio').src=job.url; $('download').href=job.url; $('download').download=`voice-studio-${job.id.slice(0,8)}.${job.format}`;} }
$('generate').onclick=async()=>{ if(!$('script').value.trim()){notify('Hãy nhập nội dung cần đọc.',true);$('script').focus();return;} $('generate').disabled=true;notify('');try { const job=await api('/api/speech',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({input_format:$('script-format').value,skip_timestamps:$('create-skip-times').checked,text:$('script').value,voice_id:$('voice').value,language:$('language').value,speed:Number($('speed').value),format:$('format').value,max_minutes:Number($('max-minutes').value),delivery:$('delivery').value,paragraph_pause:Number($('paragraph-pause').value),quality:$('quality').value,nano_steps:Number($('nano-steps').value),nano_threads:Number($('nano-threads').value),nano_parallel:Number($('nano-parallel').value)})}); activeOutputId=job.id; setOutput(job); pollJob(job.id); }catch(e){notify(e.message,true);}finally{$('generate').disabled=false;} };
async function pollJob(id) { let job; try{job=await api(`/api/jobs/${id}`);setOutput(job);if(currentTab==='history')await refreshHistory();}catch(e){notify('Mất kết nối theo dõi tác vụ. Đang thử lại: '+e.message,true);setTimeout(()=>pollJob(id),2000);return;} if(['queued','running','cancelling'].includes(job.status))setTimeout(()=>pollJob(id),job.status==='cancelling'?200:1000); }
let cloneReference={token:0,url:null,file:null,duration:0,pending:false,ready:false,prefilled:null};
function cloneStatus(message,error=false,busy=false){const node=$('clone-status');node.textContent=message;node.hidden=!message;node.classList.toggle('error-message',error);$('clone-progress').hidden=!busy;}
function cloneButtonsBusy(busy){$('clone-submit').disabled=busy;$('clone-save-test').disabled=busy;}
function resetCloneReference(){const token=cloneReference.token+1;if(cloneReference.url)URL.revokeObjectURL(cloneReference.url);const audio=$('clone-reference-audio');audio.pause();audio.removeAttribute('src');audio.hidden=true;cloneReference={token,url:null,file:null,duration:0,pending:false,ready:false,prefilled:null};for(const id of ['clone-reference-start','clone-reference-end']){$(id).value='';$(id).disabled=true;$(id).setCustomValidity('');}$('clone-listen-clip').disabled=true;$('clone-reference-info').textContent='Chọn tệp để kiểm tra và chọn đoạn tham chiếu 3–8 giây.';}
function selectedCloneClip(){const start=Number($('clone-reference-start').value),end=Number($('clone-reference-end').value);if(!cloneReference.ready||!Number.isFinite(start)||!Number.isFinite(end)||start<0||end>cloneReference.duration+.001||end-start<3||end-start>8+.001)throw Error('Chọn đoạn mẫu dài 3–8 giây, nằm trong thời lượng tệp. Lời Hmong phải khớp đúng đoạn được chọn.');return {start,end};}
function cloneClipChanged(){
 if(!isHmongStudio()||!cloneReference.ready)return;
 const prefilled=cloneReference.prefilled;let message;
 try{
  const clip=selectedCloneClip();$('clone-reference-end').setCustomValidity('');
  const same=prefilled&&Math.abs(clip.start-prefilled.start)<.001&&Math.abs(clip.end-prefilled.end)<.001;
  if(!same&&prefilled&&$('transcript').value===prefilled.text)$('transcript').value='';
  if(same&&!$('transcript').value)$('transcript').value=prefilled.text;
  const note=same?(prefilled.textVerified?'Đoạn đang chọn dùng lời mẫu do bạn cung cấp và xác nhận. Bạn có thể nghe và sửa.':'Lời gợi ý cho đoạn này chưa được xác minh khớp âm thanh; hãy nghe kiểm tra và sửa nếu cần.'):'Nhập lời Hmong khớp chính xác đoạn đang chọn.';
  message=`Tệp ${cloneReference.duration.toFixed(2)} giây · đang chọn ${clip.start.toFixed(2)}–${clip.end.toFixed(2)} giây (${(clip.end-clip.start).toFixed(2)} giây). `+note;
 }catch(e){$('clone-reference-end').setCustomValidity(e.message);if(prefilled&&$('transcript').value===prefilled.text)$('transcript').value='';message=e.message;}
 $('clone-reference-info').textContent=message;
}
$('transcript').addEventListener('input',()=>{if(isHmongStudio()&&cloneReference.prefilled){if($('transcript').value!==cloneReference.prefilled.text)$('clone-reference-info').textContent='Bạn đang sửa lời mẫu. Kiểm tra lời khớp đoạn thu trước khi lưu.';else cloneClipChanged();}});
$('clone-file').addEventListener('change',async()=>{if(!isHmongStudio())return;resetCloneReference();cloneButtonsBusy(false);$('transcript').value='';const file=$('clone-file').files[0];if(!file){cloneStatus('');return;}if(file.size>20*1024*1024){cloneStatus('Mẫu âm thanh vượt quá 20 MB.',true);return;}const token=cloneReference.token;cloneReference.file=file;cloneReference.pending=true;cloneButtonsBusy(true);cloneStatus('Đang tải và kiểm tra mẫu âm thanh, nhận diện hai MP3 gốc…',false,true);const data=new FormData();data.append('file',file);try{const info=await api('/api/hmong/reference-info',{method:'POST',body:data});if(token!==cloneReference.token)return;const duration=Number(info.duration);if(!Number.isFinite(duration)||duration<3||duration>30.02)throw Error('Chọn tệp âm thanh dài 3–30 giây, rồi lấy đoạn mẫu 3–8 giây.');cloneReference.duration=duration;cloneReference.ready=true;cloneReference.url=URL.createObjectURL(file);const audio=$('clone-reference-audio');audio.src=cloneReference.url;audio.hidden=false;for(const id of ['clone-reference-start','clone-reference-end']){$(id).disabled=false;$(id).max=String(duration);}$('clone-reference-start').value=String(info.reference_start??0);$('clone-reference-end').value=String(info.reference_end??Math.min(5,duration));$('clone-listen-clip').disabled=false;if(info.automatic&&info.known_preset&&info.transcript){const start=Number(info.reference_start),end=Number(info.reference_end);cloneReference.prefilled={start,end,text:info.transcript,textVerified:info.transcript_verified===true};$('transcript').value=info.transcript;if(!$('clone-name').value.trim())$('clone-name').value=(voices.find(v=>v.id===info.known_preset)?.name||'Giọng Hmong')+' · Cá nhân';}cloneClipChanged();cloneStatus(info.automatic?(info.transcript_verified===true?'Đã đối chiếu đúng tệp MP3 gốc và điền lời mẫu do bạn cung cấp, xác nhận khớp đoạn thu. Có thể nghe, sửa rồi lưu hoặc tạo thử.':'Đã đối chiếu đúng tệp MP3 gốc. Lời gợi ý được điền nhưng chưa được xác minh; hãy nghe và sửa cho khớp trước khi lưu hoặc tạo thử.'):'Đã kiểm tra tệp. Chọn đoạn 3–8 giây, nghe thử và nhập đúng lời Hmong trong đoạn đó.');}catch(e){if(token===cloneReference.token)cloneStatus(e.message,true);}finally{if(token===cloneReference.token){cloneReference.pending=false;cloneButtonsBusy(false);$('clone-progress').hidden=true;}}});
for(const id of ['clone-reference-start','clone-reference-end'])$(id).addEventListener('input',cloneClipChanged);
$('clone-listen-clip').onclick=async()=>{try{const clip=selectedCloneClip();const audio=$('clone-reference-audio');audio.currentTime=clip.start;await audio.play();}catch(e){cloneStatus('Không phát được đoạn mẫu: '+e.message,true);}};
$('clone-reference-audio').addEventListener('timeupdate',()=>{const audio=$('clone-reference-audio'),end=Number($('clone-reference-end').value);if(cloneReference.ready&&audio.currentTime>=end)audio.pause();});
$('clone-form').onsubmit=async(e)=>{e.preventDefault();const file=$('clone-file').files[0];if(file?.size>20*1024*1024){notify('Mẫu âm thanh vượt quá 20 MB.',true);return;}const hmong=isHmongStudio(),test=hmong&&e.submitter?.id==='clone-save-test';const data=new FormData(e.target);if(hmong){if(cloneReference.pending||!cloneReference.ready||cloneReference.file!==file){cloneStatus('Đợi kiểm tra tệp hoàn tất. Nếu có lỗi, chọn lại tệp âm thanh.',true);return;}try{const clip=selectedCloneClip();data.set('reference_start',String(clip.start));data.set('reference_end',String(clip.end));if(!$('transcript').value.trim())throw Error('Nhập chính xác lời Hmong của đoạn mẫu đang chọn.');}catch(error){cloneStatus(error.message,true);return;}}cloneButtonsBusy(true);notify('');if(hmong)cloneStatus('Đang cắt đoạn mẫu, chuẩn hóa âm thanh và lưu hồ sơ giọng…',false,true);try{const voice=await api('/api/voices/clone',{method:'POST',body:data});await refreshVoices();e.target.reset();if(hmong){resetCloneReference();$('language').value=voice.languages?.[0]||config.default_language;$('voice-source').value='all';$('create-native').value='all';updateVoiceOptions();$('voice').value=voice.id;updateVoice();showTab('create');if(test){$('script-format').value='txt';$('script').value='Nyob zoo. Ua tsaug rau koj mloog.';$('script').oninput();cloneStatus(`Đã lưu “${voice.name}”. Đang gửi yêu cầu tạo bản thu thử Hmong.`);await $('generate').onclick();}else{cloneStatus(`Đã lưu hồ sơ “${voice.name}”.`);notify(`Đã lưu “${voice.name}” và chọn giọng này. Nhập lời rồi bấm Tạo giọng để tạo bản thu thật.`);$('script').focus();}}else{showTab('voices');notify(`Đã lưu mẫu giọng “${voice.name}”. Chọn Sử dụng giọng để tạo lời đọc sau khi tải mô hình.`);}}catch(error){if(hmong)cloneStatus(error.message,true);notify(error.message,true);}finally{cloneButtonsBusy(false);$('clone-progress').hidden=true;}};
async function refreshHistory() { const items=(await api('/api/history')).items; $('history-list').replaceChildren(); if(!items.length){$('history-list').append(element('div','Chưa có bản thu. Hãy bắt đầu với câu chuyện đầu tiên của bạn.','empty'));return;} for(const item of items) { const card=element('article',undefined,'history-item card');const head=element('div',undefined,'history-head');head.append(element('span',`${item.voice_name} · ${config.languages[item.language]} · ${new Date(item.created_at).toLocaleString('vi-VN')}`),element('span',{queued:'Trong hàng đợi',running:'Đang tạo',done:'Hoàn tất',cancelled:'Đã dừng',cancelling:'Đang dừng',error:'Có lỗi'}[item.status],`status ${item.status}`)); card.append(head,element('p',item.text.length>3000 ? item.text.slice(0,3000)+'…' : item.text));card.append(element('p',`${item.phase || ''} · ${item.progress || 0}% · ${duration(item.audio_seconds || 0)}${item.duration_limited ? ' · Đã đạt giới hạn thời lượng; còn văn bản chưa đọc.' : ''}`,'form-note')); if(item.error)card.append(element('p',item.error,'error-message')); const controls=element('div',undefined,'history-controls'); if(item.status==='done') {const audio=element('audio');audio.controls=true;audio.preload='none';audio.src=item.url;const link=element('a',`Tải ${item.format.toUpperCase()} ↓`,'secondary-button');link.href=item.url;link.download=`voice-studio-${item.id.slice(0,8)}.${item.format}`;controls.append(audio,link);for(const extension of ['txt','srt']){const scriptLink=element('a','Xuất '+extension.toUpperCase(),'secondary-button');scriptLink.href=`/api/jobs/${item.id}/script.${extension}`;scriptLink.download='script.'+extension;controls.append(scriptLink);}if(item.video_url){const videoLink=element('a','Tải video MP4 ↓','secondary-button');videoLink.href=item.video_url;videoLink.download='voice-studio-'+item.id.slice(0,8)+'.mp4';controls.append(videoLink);}} if(['running','queued','cancelling'].includes(item.status)){const stop=element('button','Dừng');stop.disabled=item.status==='cancelling';stop.onclick=async()=>{try{await api(`/api/jobs/${item.id}/cancel`,{method:'POST'});await refreshHistory();}catch(e){notify(e.message,true);}};controls.append(stop);} if(['error','cancelled'].includes(item.status)){const resume=element('button','Tiếp tục');resume.onclick=async()=>{try{const job=await api(`/api/jobs/${item.id}/resume`,{method:'POST'});activeOutputId=job.id;setOutput(job);pollJob(job.id);await refreshHistory();}catch(e){notify(e.message,true);}};controls.append(resume);} if(!['running','queued','cancelling'].includes(item.status)){const del=element('button','Xóa bản thu');del.onclick=async()=>{if(!confirm('Xóa bản thu này khỏi máy?'))return;try{await api(`/api/history/${item.id}`,{method:'DELETE'});await refreshHistory();}catch(e){notify(e.message,true);}};controls.append(del);}card.append(controls);$('history-list').append(card);} if(items.some(i=>['queued','running','cancelling'].includes(i.status))&&!polling){polling=true;setTimeout(()=>{polling=false;if(currentTab==='history')refreshHistory().catch(e=>notify(e.message,true));},3000);} }
$('help-button').onclick=()=>{$('help-dialog').showModal();};$('close-help').onclick=()=>{$('help-dialog').close();};
async function init(){try{config=await api('/api/config');$('hardware').textContent=config.hardware_label||`${config.hardware} LOCAL`;for(const id of ['language','clone-language','writing-language','dub-language'])for(const [value,label]of Object.entries(config.languages)){if(id==='clone-language'&&!config.ai_voice_languages.includes(value))continue;const o=element('option',label);o.value=value;$(id).append(o);} applyStudioVariant(); $('model-status').replaceChildren(...Object.entries(config.models).map(([name,ready])=>element('p',`${ready?'●':'○'} ${name}: ${ready?'Đã tải':'Chưa tải'}`)));await refreshVoices();if(!Object.values(config.models).some(Boolean)&&!config.nano_ready&&!voices.some(v=>v.engine==='system'))notify('Studio đã mở. Cần tải mô hình AI trước khi tạo giọng nói — xem nút ? ở góc trên.');const recent=(await api('/api/history')).items[0];if(recent){activeOutputId=recent.id;setOutput(recent);if(['running','queued','cancelling'].includes(recent.status))pollJob(recent.id);}}catch(e){notify('Không kết nối được studio: '+e.message,true);}}
init();
loadConnections().catch(e=>notify(e.message,true));

function duration(seconds){seconds=Math.floor(seconds);return `${Math.floor(seconds/3600)}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
let connections;
async function loadConnections(){connections=await api('/api/writing/connections');refreshConnectionLabel();}
function refreshConnectionLabel(){const provider=$('writing-provider').value;const local=provider==='ollama';$('cloud-key-fields').hidden=local;$('local-writing-help').hidden=!local;$('disconnect-writing').hidden=local;$('writing-connected').textContent=connections?.providers[provider] ? (local?'Ollama đang chạy':'Đã kết nối') : (local?'Chưa mở Ollama':'Chưa kết nối');const available=connections?.local?.models || [];const previous=$('writing-model').value;const preferred=connections?.defaults[provider] || (local?'qwen3:4b':'');$('writing-model').value=local && available.length ? (available.includes(previous)?previous:(available.includes(preferred)?preferred:available[0])) : preferred;$('local-writing-models').replaceChildren(...(connections?.local?.models || []).map(name=>{const o=element('option');o.value=name;return o;}));}
$('writing-provider').onchange=()=>{$('writing-key').value='';refreshConnectionLabel();};
$('connect-writing').onclick=async()=>{const button=$('connect-writing');button.disabled=true;notify('');try{await api('/api/writing/connect',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:$('writing-provider').value,api_key:$('writing-key').value})});$('writing-key').value='';await loadConnections();notify($('writing-provider').value==='ollama' ? 'Đã kết nối Ollama cục bộ. Không cần API key. Kiểm tra model đã tải trong danh sách tên model.' : 'Kết nối thành công. Khóa chỉ giữ trong bộ nhớ máy chủ.');}catch(e){notify(e.message,true);}finally{button.disabled=false;}};
$('disconnect-writing').onclick=async()=>{try{await api(`/api/writing/connections/${$('writing-provider').value}`,{method:'DELETE'});await loadConnections();}catch(e){notify(e.message,true);}};
$('write-script').onclick=async()=>{if(!$('writing-prompt').value.trim()){notify('Nhập chủ đề hoặc nội dung cần viết.',true);return;}const button=$('write-script');button.disabled=true;notify('AI đang viết; CPU có thể cần vài phút. Không đóng ứng dụng hoặc Ollama.');try{const result=await api('/api/writing/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:$('writing-provider').value,model:$('writing-model').value,prompt:$('writing-prompt').value,language:$('writing-language').value,kind:$('writing-kind').value,minutes:Number($('writing-minutes').value)})});$('writing-result').value=result.text;notify((result.incomplete?'Kết quả đã chạm giới hạn trả lời. ':'')+result.note);}catch(e){notify(e.message,true);}finally{button.disabled=false;}};
function transferWriting(append){const text=$('writing-result').value.trim();if(!text){notify('Chưa có kết quả để chuyển.',true);return;}const combined=append ? $('script').value+'\n\n'+text : text;if(combined.length>200000){notify('Tổng kịch bản vượt 200.000 ký tự.',true);return;}$('script').value=combined;$('language').value=$('writing-language').value;updateVoiceOptions();$('script').oninput();showTab('create');}
$('use-writing').onclick=()=>transferWriting(false);$('append-writing').onclick=()=>transferWriting(true);
$('continue-writing').onclick=()=>{const text=$('writing-result').value.trim();if(!text){notify('Chưa có nội dung để viết tiếp.',true);return;}$('writing-prompt').value='Viết tiếp phần sau, không lặp lại nội dung đã có. Tiếp tục theo chương. Phần cuối trước đó:\n'+text.slice(-12000);$('writing-prompt').focus();notify('Đã chuẩn bị yêu cầu viết tiếp. Bấm Viết kịch bản để gửi.');};

$('stop-generation').onclick=async()=>{if(!activeOutputId)return;const button=$('stop-generation');button.disabled=true;try{const job=await api(`/api/jobs/${activeOutputId}/cancel`,{method:'POST'});setOutput(job);notify('Đã yêu cầu dừng. Các đoạn hoàn tất được giữ để tiếp tục.');}catch(e){notify(e.message,true);}finally{if(button.textContent!=='Đang dừng…')button.disabled=false;}};
document.querySelectorAll('[data-provider]').forEach(button=>button.onclick=()=>{$('writing-provider').value=button.dataset.provider;$('writing-provider').onchange();if(button.dataset.provider!=='ollama')$('writing-key').focus();});

$('use-nano').onclick=()=>{if(!config?.nano_ready){notify('Chạy download_turbo_model.bat để tải Nano, rồi tải lại trang. Nano ưu tiên tốc độ, chất lượng thấp hơn Turbo.',true);return;}$('language').value='vi';$('voice-source').value='all';updateVoiceOptions();$('voice').value='nano-minhquan';$('quality').value='auto';updateVoice();notify('Đã chọn Minh Quân · Siêu nhanh (Nano). Giọng này khác giọng trước và ưu tiên tốc độ hơn độ tự nhiên.');};

function showSpeedReport(job){const report=job.speed_report;if(!report){$('performance-result').hidden=true;return;}if(isHmongStudio()){const el=$('performance-result');el.hidden=false;el.classList.remove('error');el.textContent=`Đã đo Hmong: ${report.realtime_multiplier}× thời gian thực trên ${report.measurement_audio_seconds}s âm thanh / ${report.measurement_elapsed_seconds}s xử lý. Ước tính 1 giờ: ${Math.round(report.estimated_hour_seconds)} giây. Đây là ngoại suy từ mẫu, phụ thuộc máy, mẫu giọng và số bước.`;return;}const el=$('performance-result');el.hidden=false;el.classList.toggle('error',!report.target_30x_met_on_sample);el.textContent=`Đã đo: ${report.realtime_multiplier}× thời gian thực trên ${report.measurement_audio_seconds}s âm thanh / ${report.measurement_elapsed_seconds}s xử lý (không tính chờ hàng đợi). Ước tính tạo 1 giờ voice: ${Math.round(report.estimated_hour_seconds)} giây. ${report.target_30x_met_on_sample?'Mẫu này đạt mục tiêu 30×.':'Mẫu này chưa đạt mục tiêu 30×.'} Đây là ngoại suy từ mẫu, không bảo đảm cho bản 1 giờ hoặc giọng khác. Lượt đầu có thể chậm hơn.`;}
function applyTargetPreset(){if(!config?.nano_ready){notify('Cần tải Nano bằng download_turbo_model.bat, rồi tải lại trang.',true);return false;}$('language').value='vi';$('voice-source').value='all';updateVoiceOptions();$('voice').value='nano-minhquan';$('quality').value='auto';$('nano-steps').value='4';$('nano-threads').value='2';$('nano-parallel').value=(config.cpu_cores>=4&&config.available_ram_gb>=4?'4':config.cpu_cores>=4&&config.available_ram_gb>=3?'2':'1');$('nano-threads').value=$('nano-parallel').value==='4'?'1':'2';$('speed').value='1';$('speed').oninput();$('delivery').value='natural';$('paragraph-pause').value='0';$('format').value='wav';updateVoice();notify('Đã chọn cấu hình bản nháp ưu tiên tốc độ: Minh Quân Nano 4 bước, WAV, nhịp tự nhiên 1×, không thêm nghỉ giữa câu. Có thể giảm độ rõ/tự nhiên; chạy song song tốn thêm RAM. Chưa bảo đảm đạt 30× trên máy này.');return true;}
$('target-preset').onclick=applyTargetPreset;
$('benchmark-speed').onclick=async()=>{if(isHmongStudio()){const voice=voices.find(v=>v.id===$('voice').value);if(!voice||voice.ready===false){notify('Chọn giọng Hmong sẵn sàng trước khi đo tốc độ.',true);return;}const button=$('benchmark-speed');button.disabled=true;try{const job=await api('/api/speech',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:samples.mww,voice_id:voice.id,language:'mww',quality:'auto',format:'wav',speed:1,delivery:'natural',paragraph_pause:0,max_minutes:3})});activeOutputId=job.id;setOutput(job);pollJob(job.id);notify('Đang tạo mẫu Hmong để đo tốc độ; lời bạn đang soạn được giữ nguyên.');}catch(e){notify(e.message,true);}finally{button.disabled=false;}return;}if(!applyTargetPreset())return;const button=$('benchmark-speed');button.disabled=true;try{const text='Buổi sáng bắt đầu bằng ánh nắng dịu dàng xuyên qua khung cửa. Chúng ta dành một chút thời gian để chuẩn bị cho ngày mới, sắp xếp những công việc quan trọng và giữ tinh thần bình tĩnh. Mỗi bước đi nhỏ đều có thể tạo nên thay đổi tích cực khi được thực hiện đều đặn. Khi gặp khó khăn, hãy tạm dừng, nhìn lại mục tiêu và lựa chọn cách giải quyết phù hợp. Lắng nghe mọi người giúp chúng ta hiểu thêm những góc nhìn khác nhau. Một câu chuyện hay không chỉ cần lời kể rõ ràng mà còn cần cảm xúc chân thành. Công nghệ có thể hỗ trợ công việc sáng tạo, nhưng người kể chuyện vẫn quyết định điều muốn truyền tải. Hãy đọc lại nội dung, sửa những chỗ chưa tự nhiên và kiểm tra âm thanh trước khi chia sẻ. Chất lượng của sản phẩm cuối cùng được tạo nên từ nhiều lần thử và điều chỉnh. Chúc bạn có một ngày làm việc hiệu quả và nhiều ý tưởng mới.';const job=await api('/api/speech',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,voice_id:'nano-minhquan',language:'vi',quality:'auto',nano_steps:4,nano_threads:Number($('nano-threads').value),nano_parallel:Number($('nano-parallel').value),format:'wav',speed:1,delivery:'natural',paragraph_pause:0,max_minutes:3})});activeOutputId=job.id;setOutput(job);pollJob(job.id);notify('Đang tạo mẫu đo riêng; nội dung bạn nhập vẫn được giữ. Khi xong, xem tốc độ và ước tính bên dưới bản thu.');}catch(e){notify(e.message,true);}finally{button.disabled=false;}};

$('machine-info').onclick=async()=>{const button=$('machine-info');button.disabled=true;notify('Đang đọc cấu hình CPU, RAM và khả năng CUDA…');try{const info=await api('/api/system-info');notify(`CPU: ${info.cpu} · ${info.logical_cores || '?'} luồng · RAM: ${info.ram_gb ?? '?'} GB · NVIDIA: ${info.nvidia_gpus.length?info.nvidia_gpus.join('; '):'không phát hiện'} · PyTorch CUDA: ${info.pytorch_cuda_available===true?'dùng được':info.pytorch_cuda_available===false?'chưa dùng được':'chưa xác định'}. ${info.note}`);}catch(e){notify(e.message,true);}finally{button.disabled=false;}};

let dubSource=null,dubJob=null,dubSources=[];
async function refreshDubSources(){dubSources=(await api('/api/videos')).items;const select=$('dub-existing');select.replaceChildren(element('option','Chọn video hoặc tải mới bên dưới'));select.firstChild.value='';for(const item of dubSources){const option=element('option',`${item.name} · ${duration(item.duration)}`);option.value=item.id;select.append(option);}select.value=dubSource?.id||'';if(typeof openVideoEditor==='function')await openVideoEditor();}
$('dub-existing').onchange=()=>{dubSource=dubSources.find(v=>v.id===$('dub-existing').value)||null;$('dub-source').textContent=dubSource?`${dubSource.name} · ${duration(dubSource.duration)} · ${dubSource.codec}`:'Chưa chọn video.';$('dub-delete').hidden=!dubSource;};
$('dub-upload').onclick=async()=>{const file=$('dub-file').files[0];if(!file){notify('Chọn video trước.',true);return;}if(file.size>2*1024**3){notify('Video tối đa 2 GB.',true);return;}if(dubSource){notify('Chọn mục trống trong danh sách video để tải video mới.',true);return;}const b=$('dub-upload');b.disabled=true;$('dub-source').textContent='Đang tải và kiểm tra video…';try{const data=new FormData();data.append('file',file);$('dub-upload-progress').hidden=false;dubSource=await uploadVideo(data);$('dub-source').textContent=`${dubSource.name} · ${duration(dubSource.duration)} · ${dubSource.codec}`;$('dub-delete').hidden=false;await refreshDubSources();}catch(e){$('dub-source').textContent=e.message;notify(e.message,true);}finally{b.disabled=false;}};
$('dub-delete').onclick=async()=>{if(!dubSource)return;try{await api('/api/videos/'+dubSource.id,{method:'DELETE'});dubSource=null;$('dub-source').textContent='Đã xóa video gốc.';$('dub-delete').hidden=true;await refreshDubSources();}catch(e){notify(e.message,true);}};
$('dub-copy-script').onclick=()=>{$('dub-script').value=$('script').value;$('dub-format').value=$('script-format').value;};
function updateDub(job){dubJob=job.id;const working=['queued','running','cancelling'].includes(job.status);taskButtons(working||!!videoTaskId);$('dub-progress').value=job.progress||0;$('dub-percent').textContent=`${job.progress||0}%`;$('dub-generate').disabled=working;$('dub-voice-only').disabled=working;$('dub-stop').hidden=!working;$('dub-stop').disabled=job.status==='cancelling';$('dub-stop').textContent=job.status==='cancelling'?'Đang dừng…':'■ Dừng tạo voice / lồng tiếng / xuất';$('dub-status').textContent=job.error||`${job.status==='done'?'Video đã sẵn sàng':job.phase||'Đang chuẩn bị'} · ${job.progress||0}%`;$('dub-preview').hidden=!job.video_url||job.status!=='done';$('dub-download').hidden=$('dub-preview').hidden;const done=job.status==='done';$('dub-audio').hidden=!done;$('dub-audio-download').hidden=!done;if(done){$('dub-audio').src=job.url;$('dub-audio-download').href=job.url;$('dub-audio-download').download=`voice-${job.id.slice(0,8)}.${job.format}`;}if(job.video_url&&job.status==='done'){if(!$('dub-preview').src.endsWith(job.video_url))$('dub-preview').src=job.video_url;$('dub-download').href=job.video_url;$('dub-download').download=`voice-studio-${job.id.slice(0,8)}.mp4`;}}
async function submitDub(videoWanted){if(videoWanted&&$('logo-enabled').checked&&(!logoRect||logoVideoId!==dubSource?.id)){notify('Chọn lại vùng logo cho video hiện tại.',true);return;}if(videoWanted&&!dubSource){notify('Tải video vào studio trước.',true);return;}if(!$('dub-voice').value){notify('Chưa có giọng phù hợp với ngôn ngữ đã chọn. Tải giọng quốc tế hoặc cài giọng SAPI Windows.',true);return;}if(!$('dub-script').value.trim()){notify('Nhập lời lồng tiếng trước.',true);return;}const b=$('dub-generate');b.disabled=true;$('dub-voice-only').disabled=true;let submitted=false;try{const job=await api('/api/speech',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({input_format:$('dub-format').value,text:$('dub-script').value,voice_id:$('dub-voice').value,language:$('dub-language').value,format:'wav',speed:Number($('speed').value),quality:$('quality').value,delivery:$('delivery').value,paragraph_pause:Number($('paragraph-pause').value),max_minutes:180,nano_steps:Number($('dub-nano-steps').value),nano_threads:2,nano_parallel:Number($('dub-parallel').value),video_id:videoWanted?dubSource.id:null,video_offset:videoWanted?Number($('dub-offset').value):0,video_mix:$('dub-mix').checked,caption_style:readCaptionStyle(),caption_cues:videoWanted&&$('dub-burn-captions').checked&&editorVideoId===dubSource?.id?editorCues:[],export_resolution:$('editor-resolution').value,export_quality:$('editor-quality').value,logo:null,logos:videoWanted&&$('logo-enabled').checked?selectedLogoRegions():[]})});submitted=true;activeOutputId=job.id;updateDub(job);pollJob(job.id);}catch(e){$('dub-status').textContent=e.message;notify(e.message,true);}finally{if(!submitted){b.disabled=false;$('dub-voice-only').disabled=false;}}}
$('dub-generate').onclick=()=>submitDub(true);$('dub-voice-only').onclick=()=>submitDub(false);
$('dub-stop').onclick=async()=>{if(videoTaskId){videoAutoDub=false;await api('/api/video-tasks/'+videoTaskId+'/cancel',{method:'POST'});return;}if(!dubJob)return;try{await api('/api/jobs/'+dubJob+'/cancel',{method:'POST'});}catch(e){notify(e.message,true);}};

function updateDubVoices(){const old=$('dub-voice').value;const source=$('dub-voice-source').value;const options=voices.filter(v=>v.languages.includes($('dub-language').value)&&(source==='all'||(source==='system'?v.engine==='system':v.engine!=='system')));$('dub-voice').replaceChildren(...options.map(v=>{const o=element('option',v.name+(v.native_language?' · '+(config.languages[v.native_language]||({'en':'Mỹ / Anh'}[v.native_language]||v.native_language)):'')+(v.ready===false?' · Chưa tải model':' · Sẵn sàng'));o.value=v.id;return o;}));if(options.some(v=>v.id===old))$('dub-voice').value=old;else{const ready=options.find(v=>v.engine==='system'||(v.engine==='vieneu_nano'?config?.nano_ready:config?.models[v.engine]));if(ready)$('dub-voice').value=ready.id;}updateDubVoiceInfo();}
function updateDubVoiceInfo(){const voice=voices.find(v=>v.id===$('dub-voice').value);$('dub-voice-info').textContent=voice?`${voice.name} · ${voice.description}${voice.ready===false?' · CHƯA TẢI: bấm Tải model cho giọng đang chọn.':' · Sẵn sàng'}`:'Nguồn Windows chưa có giọng cho ngôn ngữ này. Chọn Tất cả giọng hoặc Giọng AI cục bộ, rồi bấm Tải model. Giọng Windows cần cài trong Settings > Time & language > Speech; OneCore không phải giọng SAPI.';if(typeof syncVoiceDownload==='function')syncVoiceDownload('dub');}
$('dub-language').onchange=updateDubVoices;$('dub-voice-source').onchange=updateDubVoices;$('dub-voice').onchange=updateDubVoiceInfo;$('voice-source').onchange=updateVoiceOptions;
async function importScript(file,editor,format){if(!file)return;if(file.size>2*1024**2){notify('Tệp tối đa 2 MB.',true);return;}const text=(await file.text()).replace(/^\uFEFF/,'');if(text.length>200000){notify('Tối đa 200.000 ký tự.',true);return;}const kind=file.name.toLowerCase().endsWith('.srt')?'srt':'txt';if(kind==='srt'){try{await api('/api/scripts/convert',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,input_format:'srt',output_format:'srt'})});}catch(e){notify(e.message,true);return;}}$(editor).value=text;$(format).value=kind;if(editor==='script')$('script').oninput();notify(`Đã nhập ${kind.toUpperCase()}${kind==='srt'?' và giữ mốc thời gian từng câu':''}.`);}
$('import-script').onchange=()=>importScript($('import-script').files[0],'script','script-format');$('dub-import').onchange=()=>importScript($('dub-import').files[0],'dub-script','dub-format');
function downloadText(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const link=element('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function exportScript(editor,format,extension,jobId){const text=$(editor).value;if(!text.trim()){notify('Chưa có lời đọc.',true);return;}try{if(extension==='srt'&&$(format).value==='srt'&&jobId){const job=await api('/api/jobs/'+jobId);if(job.text.trim()===text.trim()&&job.input_format==='srt'&&job.status==='done'){const response=await fetch(`/api/jobs/${jobId}/script.srt`);if(response.ok){downloadText(await response.text(),'voice-studio.srt');return;}}}if(extension==='srt'&&$(format).value==='txt'){if(!jobId)throw Error('Tạo giọng hoàn tất trước khi xuất SRT để có mốc thời gian thực.');const job=await api('/api/jobs/'+jobId);if(job.text.trim()!==text.trim()||job.input_format==='srt'||job.status!=='done')throw Error('Nội dung đã đổi hoặc tác vụ chưa xong. Tạo lại voice để xuất SRT đúng lời.');const response=await fetch(`/api/jobs/${jobId}/script.srt`);if(!response.ok)throw Error('SRT chưa sẵn sàng.');downloadText(await response.text(),'voice-studio.srt');return;}const result=await api('/api/scripts/convert',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,input_format:$(format).value,output_format:extension})});downloadText(result.text,'voice-studio.'+extension);}catch(e){notify(e.message,true);}}
$('export-script-txt').onclick=()=>exportScript('script','script-format','txt',activeOutputId);$('export-script-srt').onclick=()=>exportScript('script','script-format','srt',activeOutputId);$('dub-export-txt').onclick=()=>exportScript('dub-script','dub-format','txt',dubJob);$('dub-export-srt').onclick=()=>exportScript('dub-script','dub-format','srt',dubJob);

function uploadVideo(data){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/videos');xhr.responseType='json';xhr.upload.onprogress=(event)=>{if(event.lengthComputable){const percent=Math.round(100*event.loaded/event.total);$('dub-upload-progress').value=percent;$('dub-source').textContent=percent===100?'Tải lên 100% · Đang kiểm tra video…':`Đang tải video: ${percent}%`;}};xhr.onload=()=>{if(xhr.status>=200&&xhr.status<300)resolve(xhr.response);else reject(Error(xhr.response?.detail||'Không tải được video.'));};xhr.onerror=()=>reject(Error('Mất kết nối khi tải video.'));xhr.send(data);});}
let videoTaskId=null,videoAutoDub=false,logoRect=null,logoImage=null,logoStart=null,logoVideoId=null;
function taskButtons(busy){if(isHmongStudio())for(const id of ['hmong-steps','dub-hmong-steps','delivery','dub-hmong-delivery','hmong-emotion','dub-hmong-emotion','hmong-emotion-strength','dub-hmong-emotion-strength','hmong-auto-rhythm','dub-hmong-auto-rhythm','paragraph-pause','dub-hmong-paragraph-pause'])$(id).disabled=busy;for(const id of ['dub-existing','dub-upload','dub-delete','dub-language','dub-voice','dub-voice-source'])$(id).disabled=busy;for(const id of ['auto-subtitles','translate-existing','auto-dub','logo-export','dub-generate','dub-voice-only','editor-render','editor-dub','editor-recognize','editor-save','editor-add','editor-translate','editor-export-video','editor-export-txt','editor-export-srt','editor-resolution','editor-quality','export-maximum','studio-fast','subtitle-provider','subtitle-target','asr-language','dub-translate-voice','dub-translation-provider','dub-translation-model','dub-burn-captions'])$(id).disabled=busy;$('dub-stop').hidden=!busy;}
async function beginVideoTask(action,existing=false,autoDub=false){if(isHmongStudio()&&action==='subtitles'&&!existing){notify('Chưa có nhận dạng Hmong từ video. Nhập SRT hoặc thêm/sửa lời thủ công trước.',true);return;}if(autoDub&&$('translate-subtitles').checked&&$('subtitle-target').value!==$('dub-language').value&&!$('dub-translate-voice').checked){const message='Ngôn ngữ phụ đề khác ngôn ngữ giọng đọc. Bật Dịch lời lồng tiếng riêng hoặc chọn cùng ngôn ngữ trước.';$('dub-status').textContent=message;notify(message,true);return;}if(videoTaskId){notify('Dừng tác vụ hiện tại trước.',true);return;}if(!dubSource){notify('Chọn video trước.',true);return;}if(action==='logo'&&(!logoRect||logoVideoId!==dubSource.id)){notify('Hiện khung hình và chọn vùng logo của video này trước.',true);return;}if(existing&&$('dub-format').value!=='srt'){notify('Chọn định dạng SRT và nhập phụ đề trước.',true);return;}videoAutoDub=autoDub;taskButtons(true);for(const id of ['dub-preview','dub-download','dub-audio','dub-audio-download'])$(id).hidden=true;$('dub-progress').value=0;$('dub-percent').textContent='0%';try{const task=await api('/api/video-tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({video_id:dubSource.id,action,export_resolution:$('editor-resolution').value,export_quality:$('editor-quality').value,source_language:$('asr-language').value,accurate:$('asr-quality').value==='accurate',provider:$('subtitle-provider').value,target_language:$('translate-subtitles').checked?$('subtitle-target').value:'',model:$('subtitle-model').value,srt:existing?$('dub-script').value:'',logo:null,logos:selectedLogoRegions()})});videoTaskId=task.id;await pollVideoTask();}catch(e){$('dub-status').textContent=e.message;notify(e.message,true);videoTaskId=null;taskButtons(false);}}
async function pollVideoTask(){const id=videoTaskId;if(!id)return;try{const task=await api('/api/video-tasks/'+id);$('dub-progress').value=task.progress;$('dub-percent').textContent=task.progress+'%';$('dub-status').textContent=task.error||(task.status==='cancelled'?'Đã dừng':`${task.phase} · ${task.progress}%`);if(['queued','running'].includes(task.status)){setTimeout(pollVideoTask,1000);return;}videoTaskId=null;taskButtons(false);if(task.status==='done'&&task.width)$('dub-status').textContent+=` · ${task.width} × ${task.height}`;if(task.original_srt){$('dub-script').value=task.original_srt;$('dub-format').value='srt';}if(task.status==='done'){if(task.cues&&typeof loadDirectCues==='function'&&task.video_id===dubSource?.id)await loadDirectCues(task.cues);if(task.srt){$('dub-script').value=task.srt;$('dub-format').value='srt';$('dub-offset').value=0;if(videoAutoDub){videoAutoDub=false;await submitDub(true);}}if(task.video_url){$('dub-preview').hidden=false;$('dub-preview').src=task.video_url;$('dub-download').hidden=false;$('dub-download').href=task.video_url;$('dub-download').download='video-logo.mp4';}}videoAutoDub=false;}catch(e){$('dub-status').textContent='Mất kết nối theo dõi, đang thử lại… '+e.message;setTimeout(pollVideoTask,2000);}}
$('auto-subtitles').onclick=()=>beginVideoTask('subtitles');$('translate-existing').onclick=()=>{if(!$('translate-subtitles').checked){notify('Bật Dịch sang ngôn ngữ lời đọc trước.',true);return;}beginVideoTask('subtitles',true);};$('auto-dub').onclick=()=>beginVideoTask('subtitles',false,true);$('logo-export').onclick=()=>beginVideoTask('logo');
function paintLogo(){const canvas=$('logo-canvas'),ctx=canvas.getContext('2d');ctx.drawImage(logoImage,0,0,canvas.width,canvas.height);if(logoRect){ctx.strokeStyle='#ff3355';ctx.lineWidth=3;ctx.strokeRect(logoRect.x,logoRect.y,logoRect.w,logoRect.h);$('logo-region').textContent=`Vùng logo: x=${logoRect.x}, y=${logoRect.y}, rộng=${logoRect.w}, cao=${logoRect.h}`;}}
$('logo-frame').onclick=()=>{if(!dubSource){notify('Chọn video trước.',true);return;}const id=dubSource.id;const image=new Image();image.onload=()=>{if(dubSource?.id!==id)return;logoImage=image;logoVideoId=id;logoRect=null;const c=$('logo-canvas');c.width=image.naturalWidth;c.height=image.naturalHeight;c.hidden=false;paintLogo();};image.onerror=()=>notify('Không lấy được khung hình video.',true);image.src='/api/videos/'+id+'/frame?at='+encodeURIComponent($('editor-video')?.currentTime||Number($('editor-seek')?.value)||0);};
function logoPoint(e){const c=$('logo-canvas'),r=c.getBoundingClientRect();return {x:Math.max(1,Math.min(c.width-2,Math.round((e.clientX-r.left)*c.width/r.width))),y:Math.max(1,Math.min(c.height-2,Math.round((e.clientY-r.top)*c.height/r.height)))};}
$('logo-canvas').onpointerdown=e=>{logoStart=logoPoint(e);$('logo-canvas').setPointerCapture(e.pointerId);};$('logo-canvas').onpointermove=e=>{if(!logoStart)return;const p=logoPoint(e);logoRect={x:Math.min(p.x,logoStart.x),y:Math.min(p.y,logoStart.y),w:Math.abs(p.x-logoStart.x),h:Math.abs(p.y-logoStart.y)};paintLogo();};$('logo-canvas').onpointerup=()=>{logoStart=null;};
